close all
clear

%% -------------------------------------------------
% ORIGINAL PATH (DO NOT CHANGE GEOMETRY)
% Square at z = 1 m
%% -------------------------------------------------
path_xy = [
    1.0 4.0;
    1.0 5.0;
    0.0 5.0;
    0.0 4.0;
    1.0 4.0    % close loop
];

corners = [
    1.0 4.0;
    1.0 5.0;
    0.0 5.0;
    0.0 4.0
];

z_ref = 1.0;

%% -------------------------------------------------
% COMPUTE CORNER YAW ANGLES (LOOK-AHEAD)
%% -------------------------------------------------
N = size(path_xy,1);
yaw = zeros(N,1);

for i = 1:N-1
    d = path_xy(i+1,:) - path_xy(i,:);
    yaw(i) = atan2(d(2), d(1));
end
yaw(end) = yaw(end-1);   % hold last yaw

%% -------------------------------------------------
% BUILD POINTS ARRAY FOR mstraj
% [x y z roll pitch yaw]
%% -------------------------------------------------
points = zeros(N,6);

points(:,1:2) = path_xy;
points(:,3)   = z_ref;
points(:,6)   = yaw;

% Roll & pitch remain zero
points(:,4:5) = 0;

%% -------------------------------------------------
% mstraj PARAMETERS (CORRECT SEMANTICS)
%% -------------------------------------------------
qdmax = [ ...
    0.4  0.4  0.2 ...   % x y z rates
    0.8  0.8  1.2 ];   % roll pitch yaw rates

DT   = 0.02;   % trajectory sample time
TACC = 0.4;    % acceleration time

%% -------------------------------------------------
% GENERATE SMOOTH TRAJECTORY
%% -------------------------------------------------
traj = mstraj( ...
    points(2:end,:), ...  % waypoints to move through
    qdmax, ...
    [], ...               % auto time per segment
    points(1,:), ...      % initial state
    DT, ...
    TACC);

%% -------------------------------------------------
% VISUALIZATION
%% -------------------------------------------------
figure %[output:3664ac79]
plot3(traj(:,1), traj(:,2), traj(:,3), 'LineWidth', 1.5) %[output:3664ac79]
grid on %[output:3664ac79]
xlabel('X'), ylabel('Y'), zlabel('Z') %[output:3664ac79]
title('mstraj-smoothed square trajectory') %[output:3664ac79]
axis equal %[output:3664ac79]

figure %[output:249d3337]
plot(traj(:,6)) %[output:249d3337]
grid on %[output:249d3337]
xlabel('Sample') %[output:249d3337]
ylabel('Yaw [rad]') %[output:249d3337]
title('Yaw profile (anticipates corners)') %[output:249d3337]


